static class X {
 [StructLayout(LayoutKind.Sequential)] public struct RECT {public int L,T,R,B;}
 [StructLayout(LayoutKind.Sequential)] public struct CI {public int Size,Flags;public IntPtr Handle;public Native.POINT Pos;}
 public delegate bool EnumProc(IntPtr h,IntPtr p);
 public delegate void EventProc(IntPtr hook,uint e,IntPtr h,int obj,int child,uint thread,uint time);
 [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h,IntPtr after,int x,int y,int cx,int cy,uint flags);
 [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb,IntPtr p);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] public static extern int GetClassNameW(IntPtr h,StringBuilder s,int n);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h,out RECT r);
 [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr h,ref Native.POINT p);
 [DllImport("user32.dll")] public static extern IntPtr WindowFromPoint(Native.POINT p);
 [DllImport("user32.dll")] public static extern bool GetCursorInfo(ref CI i);
 [DllImport("user32.dll")] public static extern bool PostMessageW(IntPtr h,uint m,IntPtr w,IntPtr l);
