 public static long Now=>Stopwatch.GetTimestamp();
 public static double Ms(long q)=>q*1000.0/Stopwatch.Frequency;
 public static CI Cursor(){CI c=new(){Size=Marshal.SizeOf<CI>()};if(!GetCursorInfo(ref c))throw new Exception("GetCursorInfo");return c;}
 public static uint Pid(IntPtr h){GetWindowThreadProcessId(h,out var p);return p;}
 public static string Class(IntPtr h){var b=new StringBuilder(256);GetClassNameW(h,b,256);return b.ToString();}
 public static List<IntPtr> Windows(){var a=new List<IntPtr>();EnumWindows((h,p)=>{if(IsWindowVisible(h))a.Add(h);return true;},IntPtr.Zero);return a;}
