record Backup(uint Role,string Hash,int Width,int Height,int HotX,int HotY);
record HostCommand(int Serial,uint Role,bool Private);
record HostAck(int Serial,uint Role,bool Private,long Handle,int Pid,long Qpc);
record Op(long Before,long After,uint Role,int Frame,int Size,bool Ok,int Error,long HandleAfter,int X,int Y,uint OwnerPid);
record Ev(long Qpc,uint Event,int Object,long Handle);
sealed class Host : Form {
 readonly string root;readonly System.Windows.Forms.Timer timer=new(){Interval=15};int serial;IntPtr handle;bool own;
 public Host(string root){this.root=root;Text="CursorShake — propietario externo de prueba";Bounds=new Rectangle(100,130,700,360);TopMost=true;ShowInTaskbar=false;BackColor=Color.FromArgb(25,35,50);Paint+=(s,e)=>e.Graphics.DrawString("Proceso independiente: Windows selecciona su cursor.\nLa publicación se hace desde otro proceso.",SystemFonts.MessageBoxFont!,Brushes.White,25,35);timer.Tick+=(s,e)=>Read();Shown+=(s,e)=>timer.Start();}
 void Log(string why){File.AppendAllText(Path.Combine(root,"host-selections.jsonl"),JsonSerializer.Serialize(new{Qpc=X.Now,Why=why,Serial=serial,Handle=handle.ToInt64()})+"\n");}
 void Read(){if(File.Exists(Path.Combine(root,"host-stop"))){Close();return;}var p=Path.Combine(root,"command.json");if(!File.Exists(p))return;HostCommand? c;try{c=JsonSerializer.Deserialize<HostCommand>(File.ReadAllText(p));}catch{return;}if(c==null||c.Serial==serial)return;var next=Native.LoadCursorW(IntPtr.Zero,new IntPtr(c.Role));if(next==IntPtr.Zero)throw new Exception("Host LoadCursor "+c.Role);if(c.Private){next=Native.CopyImage(next,2,0,0,0);if(next==IntPtr.Zero)throw new Exception("Host CopyImage");}var old=handle;var oldOwn=own;handle=next;own=c.Private;serial=c.Serial;Cursor=new Cursor(handle);Native.SetCursor(handle);Log("command-select");if(oldOwn)Native.DestroyCursor(old);File.WriteAllText(Path.Combine(root,"ack.json"),JsonSerializer.Serialize(new HostAck(serial,c.Role,c.Private,handle.ToInt64(),Environment.ProcessId,X.Now)));}
 protected override void WndProc(ref Message m){if(m.Msg==0x20&&handle!=IntPtr.Zero){if(File.Exists(Path.Combine(root,"host-frozen"))){Log("WM_SETCURSOR-suppressed");m.Result=new IntPtr(1);return;}Native.SetCursor(handle);Log("WM_SETCURSOR");m.Result=new IntPtr(1);return;}base.WndProc(ref m);}
 protected override void Dispose(bool disposing){timer.Dispose();if(own&&handle!=IntPtr.Zero)Native.DestroyCursor(handle);base.Dispose(disposing);}
}
static class Program {
 static readonly JsonSerializerOptions Json=new(){WriteIndented=true,IncludeFields=true};
 static readonly uint[] Roles={32516,32651,32631,32671,32672,32512};
 static string root="";static readonly Dictionary<uint,Backup> backups=new();static readonly List<object> cases=new();static readonly List<Op> ops=new();static readonly List<object> restores=new();static readonly Dictionary<(int,int),IntPtr> templates=new();static int serial;static DesktopPointerCapture? capture;static Process? host,watch;static IntPtr hostWindow;
 static string Flag(uint r)=>Path.Combine(root,$"restore-{r}.required");
 static Process Spawn(params string[] args){var p=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};foreach(var a in args)p.ArgumentList.Add(a);return Process.Start(p)??throw new Exception("Spawn");}
 [STAThread] static int Main(string[] args){try{if(args[0]=="--host"){Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();Application.Run(new Host(args[1]));return 0;}if(args[0]=="--restore")return Watch(args);if(args[0]=="--inventory"){Console.WriteLine(JsonSerializer.Serialize(X.Windows().Select(h=>new{H=h.ToInt64(),Class=X.Class(h),Pid=X.Pid(h)}),Json));return 0;}root=Path.GetFullPath(args[0]);if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("Artifacts directory must be new or empty; preserve prior restoration data.");Directory.CreateDirectory(root);Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);return Run();}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static int Watch(string[] args){root=args[2];int pid=int.Parse(args[1]);var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<90000){try{if(Process.GetProcessById(pid).HasExited)break;}catch{break;}Thread.Sleep(100);}var results=new List<object>();foreach(var b in JsonSerializer.Deserialize<Backup[]>(File.ReadAllText(Path.Combine(root,"backups.json")))!){if(!File.Exists(Flag(b.Role)))continue;try{var h=Native.Load(Path.Combine(root,$"baseline-{b.Role}.cur"),0);bool ok=Native.SetSystemCursor(h,b.Role);bool match=ok&&Native.PixelHash(Native.LoadCursorW(IntPtr.Zero,new IntPtr(b.Role)))==b.Hash;if(match)File.Delete(Flag(b.Role));results.Add(new{b.Role,ok,match});}catch(Exception e){results.Add(new{b.Role,error=e.Message});}}File.WriteAllText(Path.Combine(root,"watchdog.json"),JsonSerializer.Serialize(results,Json));return Directory.GetFiles(root,"restore-*.required").Length==0?0:2;}
 static void BackupAll(){foreach(uint role in Roles){var h=Native.LoadCursorW(IntPtr.Zero,new IntPtr(role));if(h==IntPtr.Zero){cases.Add(new{Name="backup",Role=role,Status="Unavailable"});continue;}var d=Native.Dimensions(h);string hash=Native.PixelHash(h);var path=Path.Combine(root,$"baseline-{role}.cur");File.WriteAllBytes(path,Native.SaveStaticCursor(h));var disk=Native.Load(path,0);try{if(Native.PixelHash(disk)!=hash||Native.Dimensions(disk)!=d)throw new Exception("Backup roundtrip "+role);}finally{Native.DestroyCursor(disk);}backups.Add(role,new(role,hash,d.W,d.H,d.X,d.Y));}File.WriteAllText(Path.Combine(root,"backups.json"),JsonSerializer.Serialize(backups.Values,Json));watch=Spawn("--restore",Environment.ProcessId.ToString(),root);}
 static string Fixture(int f,int size){var path=Path.Combine(root,$"frame-{f}-{size}.cur");if(!File.Exists(path)){byte[] pix=new byte[size*size*4],mask=new byte[((size+31)/32)*4*size];for(int i=0;i<size*size;i++){pix[i*4]=(byte)Fixtures.Colors[f][2];pix[i*4+1]=(byte)Fixtures.Colors[f][1];pix[i*4+2]=(byte)Fixtures.Colors[f][0];pix[i*4+3]=255;}File.WriteAllBytes(path,Fixtures.Cur(size,size,size/8,size/8,pix,mask));}return path;}
 static Op Publish(uint role,int frame,int size){if(!backups.ContainsKey(role))throw new Exception("No backup "+role);if(!File.Exists(Flag(role)))File.WriteAllText(Flag(role),"restore from verified baseline");var h=Native.CopyImage(templates[(frame,size)],2,0,0,0);if(h==IntPtr.Zero)throw new Exception("Copy static template");long before=X.Now;bool ok=Native.SetSystemCursor(h,role);int error=ok?0:Marshal.GetLastWin32Error();long after=X.Now;var c=X.Cursor();var op=new Op(before,after,role,frame,size,ok,error,c.Handle.ToInt64(),c.Pos.X,c.Pos.Y,X.Pid(X.WindowFromPoint(c.Pos)));ops.Add(op);return op;}
 static void Restore(uint role){if(!File.Exists(Flag(role)))return;var b=backups[role];var present=Native.LoadCursorW(IntPtr.Zero,new IntPtr(role));if(Native.PixelHash(present)==b.Hash && Native.Dimensions(present)==(b.Width,b.Height,b.HotX,b.HotY)){restores.Add(new{Role=role,Ok=true,Match=true,AlreadyBaseline=true});File.Delete(Flag(role));return;}var h=Native.Load(Path.Combine(root,$"baseline-{role}.cur"),0);bool ok=Native.SetSystemCursor(h,role);var shared=Native.LoadCursorW(IntPtr.Zero,new IntPtr(role));var d=Native.Dimensions(shared);bool match=ok&&Native.PixelHash(shared)==b.Hash&&d==(b.Width,b.Height,b.HotX,b.HotY);restores.Add(new{Role=role,Ok=ok,Match=match});if(!match)throw new Exception("Restore mismatch "+role);File.Delete(Flag(role));}
 static HostAck Command(uint role,bool priv=false){File.Delete(Path.Combine(root,"host-frozen"));int n=++serial;File.WriteAllText(Path.Combine(root,"command.tmp"),JsonSerializer.Serialize(new HostCommand(n,role,priv)));File.Move(Path.Combine(root,"command.tmp"),Path.Combine(root,"command.json"),true);var until=Stopwatch.StartNew();while(until.ElapsedMilliseconds<3000){try{var a=JsonSerializer.Deserialize<HostAck>(File.ReadAllText(Path.Combine(root,"ack.json")));if(a?.Serial==n)return a;}catch{}Thread.Sleep(10);}throw new Exception("Host command timeout");}
 static void Delay(int ms){Thread.Sleep(ms);if(capture?.Failure!=null)throw capture.Failure;}
 static ShapeSample? Observe(Op op,int ms=180){Delay(ms);return capture!.Samples.FirstOrDefault(s=>s.Qpc>=op.Before&&s.Frame==op.Frame&&s.Width==op.Size);}
 static void HostCase(uint role,bool priv=false){if(!backups.ContainsKey(role))return;try{Restore(role);var ack=Command(role,priv);Native.SetForegroundWindow(hostWindow);Native.SetCursorPos(400,320);Delay(200);var c=X.Cursor();if(X.Pid(X.WindowFromPoint(c.Pos))!=host!.Id||c.Handle.ToInt64()!=ack.Handle)throw new Exception("Host does not own selected cursor");File.WriteAllText(Path.Combine(root,"host-frozen"),"");Delay(50);long start=X.Now;var observations=new List<object>();foreach(var (f,size) in new[]{(0,32),(1,64),(2,96),(3,32)}){var op=Publish(role,f,size);var s=Observe(op);observations.Add(new{op.Ok,op.Error,Frame=f,Size=size,Observed=s!=null,LatencyMs=s==null?(double?)null:X.Ms(s.Qpc-op.Before),SelectedHandleStable=op.HandleAfter==ack.Handle,OwnerPid=op.OwnerPid});}long end=X.Now;var selects=File.ReadAllLines(Path.Combine(root,"host-selections.jsonl")).Select(l=>JsonDocument.Parse(l)).Count(d=>d.RootElement.GetProperty("Qpc").GetInt64()>=start&&d.RootElement.GetProperty("Qpc").GetInt64()<=end&&d.RootElement.GetProperty("Why").GetString()!="WM_SETCURSOR-suppressed");cases.Add(new{Name=priv?"private-copy-negative-control":"external-host-static",Role=role,HostPid=ack.Pid,PublisherPid=Environment.ProcessId,SelectionsDuringMeasurement=selects,Observations=observations,Status="Observed"});}catch(Exception e){cases.Add(new{Name="host-case",Role=role,Private=priv,Status="Failed",Error=e.ToString()});}finally{Restore(role);}}
 static void Timeline(){uint role=32516;Restore(role);var ack=Command(role);Native.SetForegroundWindow(hostWindow);Native.SetCursorPos(400,320);Delay(200);File.WriteAllText(Path.Combine(root,"host-frozen"),"");Delay(50);long origin=X.Now;var results=new List<object>(); // The source ANI rates are 300/500/700/900 ms. Scale changes never alter origin.
  foreach(var a in new[]{(0,0,32),(300,1,32),(500,1,64),(800,2,64),(1000,2,96),(1200,2,64),(1500,3,64),(2000,3,32),(2400,0,32),(2700,1,32),(2900,1,64),(3200,2,64),(3400,2,96),(3600,2,32),(3900,3,32)}){while(X.Ms(X.Now-origin)<a.Item1)Thread.Sleep(1);var op=Publish(role,a.Item2,a.Item3);results.Add(new{DueMs=a.Item1,Frame=a.Item2,Size=a.Item3,ActualMs=X.Ms(op.Before-origin),op.Ok,op.Error});}
  Delay(500);long end=X.Now;cases.Add(new{Name="own-timeline-two-cycles",Role=role,OriginQpc=origin,EndQpc=end,HostHandle=ack.Handle,Actions=results,Status="Observed"});Restore(role);}
 static void Explorer(){uint role=32512;var w=X.Windows().FirstOrDefault(h=>X.Class(h)=="CabinetWClass");bool opened=false;if(w==IntPtr.Zero){var psi=new ProcessStartInfo("explorer.exe"){UseShellExecute=true};psi.ArgumentList.Add(root);Process.Start(psi)?.Dispose();var wait=Stopwatch.StartNew();while(wait.ElapsedMilliseconds<5000){w=X.Windows().FirstOrDefault(h=>X.Class(h)=="CabinetWClass");if(w!=IntPtr.Zero){opened=true;break;}Thread.Sleep(50);}}if(w==IntPtr.Zero){cases.Add(new{Name="explorer",Status="Skipped",Reason="Explorer did not open"});return;}try{if(opened)X.SetWindowPos(w,new IntPtr(-1),0,0,0,0,0x13);Native.SetForegroundWindow(w);Delay(1200);X.GetClientRect(w,out var r);Native.POINT p=new(){X=(r.R-r.L)/2,Y=(r.B-r.T)*2/3};X.ClientToScreen(w,ref p);Native.SetCursorPos(p.X,p.Y);Delay(300);var c=X.Cursor();var shared=Native.LoadCursorW(IntPtr.Zero,new IntPtr(role));uint pid=X.Pid(w);if(c.Handle!=shared||X.Pid(X.WindowFromPoint(c.Pos))!=pid)throw new Exception($"Explorer point invalid: rect={r.L},{r.T},{r.R},{r.B}, point={c.Pos.X},{c.Pos.Y}, owner={X.Pid(X.WindowFromPoint(c.Pos))}, expected={pid}, class={X.Class(X.WindowFromPoint(c.Pos))}, cursor={c.Handle}, arrow={shared}; no mutation made");var observations=new List<object>();foreach(var a in new[]{(0,32),(1,64),(2,96),(3,32)}){var op=Publish(role,a.Item1,a.Item2);var s=Observe(op);observations.Add(new{Frame=a.Item1,Size=a.Item2,op.Ok,op.Error,Observed=s!=null,LatencyMs=s==null?(double?)null:X.Ms(s.Qpc-op.Before),op.OwnerPid,PositionUnchanged=op.X==p.X&&op.Y==p.Y,HandleStable=op.HandleAfter==shared.ToInt64()});}cases.Add(new{Name="explorer",Status="Observed",OwnerPid=pid,PublisherPid=Environment.ProcessId,Observations=observations});}catch(Exception e){cases.Add(new{Name="explorer",Status="Skipped",Reason=e.Message});}finally{Restore(role);if(opened){X.SetWindowPos(w,new IntPtr(-2),0,0,0,0,0x13);X.PostMessageW(w,0x10,IntPtr.Zero,IntPtr.Zero);}}}
 static int Run(){Native.GetCursorPos(out var pos);var foreground=Native.GetForegroundWindow();string? failure=null;int exit=1;var oldUtility=Process.GetProcessesByName("ShakeToFindCursor-x64").Select(p=>p.Id).ToArray();try{foreach(int f in Enumerable.Range(0,4))foreach(int z in new[]{32,64,96})templates.Add((f,z),Native.Load(Fixture(f,z),z));BackupAll();capture=new DesktopPointerCapture();capture.Start();host=Spawn("--host",root);var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<4000){hostWindow=X.Windows().FirstOrDefault(h=>X.Pid(h)==host.Id);if(hostWindow!=IntPtr.Zero)break;Thread.Sleep(30);}if(hostWindow==IntPtr.Zero)throw new Exception("Host window not found");foreach(uint r in Roles.Where(r=>r!=32512))HostCase(r);HostCase(32516,true);Timeline();File.WriteAllText(Path.Combine(root,"host-stop"),"");host.WaitForExit(2000);Explorer();exit=0;}catch(Exception e){failure=e.ToString();}finally{foreach(uint r in backups.Keys){try{Restore(r);}catch(Exception e){failure+="\nRESTORE "+e;exit=2;}}File.WriteAllText(Path.Combine(root,"host-stop"),"");if(host!=null&&!host.HasExited){host.WaitForExit(2000);if(!host.HasExited)X.PostMessageW(hostWindow,0x10,IntPtr.Zero,IntPtr.Zero);}Native.SetForegroundWindow(foreground);Native.SetCursorPos(pos.X,pos.Y);capture?.Dispose();foreach(var h in templates.Values)Native.DestroyCursor(h);if(watch!=null)watch.WaitForExit(100);var report=new{Experiment="Cross-process native static frame publication; not product implementation",Date=DateTimeOffset.Now,OS=Environment.OSVersion.VersionString,QpcFrequency=Stopwatch.Frequency,PublisherPid=Environment.ProcessId,PublisherCallsSetCursor=false,Failure=failure,ExitCode=exit,OriginalUtilityPids=oldUtility,OriginalUtilityStillRunning=oldUtility.All(p=>{try{return !Process.GetProcessById(p).HasExited;}catch{return false;}}),Backups=backups.Values,Restores=restores,RemainingRestoreFlags=Directory.GetFiles(root,"restore-*.required").Select(Path.GetFileName),Cases=cases,Operations=ops,Samples=capture?.Samples.ToArray()};File.WriteAllText(Path.Combine(root,"report.json"),JsonSerializer.Serialize(report,Json));Console.WriteLine(JsonSerializer.Serialize(new{exit,failure,Cases=cases,Restores=restores},Json));}return exit;}
}
